<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\Quartier; use App\Models\AlerteMeteo; use App\Services\OpenMeteoService; use App\Services\WeatherAlertService; use Illuminate\Http\Request;
class QuartierController extends Controller { private function data(Request $r):array{return $r->validate(['nom'=>'required|string|max:255','ville'=>'required|string|max:255','code_postal'=>'nullable|string|max:20','latitude'=>'required|numeric|between:-90,90','longitude'=>'required|numeric|between:-180,180','actif'=>'nullable|boolean'])+['actif'=>$r->boolean('actif')];} public function index(){return view('admin.quartiers.index',['quartiers'=>Quartier::withCount('alertesMeteo')->latest()->get()]);} public function create(){return view('admin.quartiers.form',['quartier'=>new Quartier]);} public function store(Request $r){Quartier::create($this->data($r));return redirect()->route('admin.quartiers.index')->with('success','Quartier créé.');} public function show(Quartier $quartier){return view('admin.quartiers.show',compact('quartier'));} public function edit(Quartier $quartier){return view('admin.quartiers.form',compact('quartier'));} public function update(Request $r,Quartier $quartier){$quartier->update($this->data($r));return redirect()->route('admin.quartiers.show',$quartier)->with('success','Quartier modifié.');} public function destroy(Quartier $quartier){$quartier->delete();return redirect()->route('admin.quartiers.index')->with('success','Quartier supprimé.');} public function generate(Quartier $quartier,OpenMeteoService $meteo,WeatherAlertService $levels){try{$w=$meteo->weather($quartier);$niveau=$levels->niveau($w['temperature']);AlerteMeteo::updateOrCreate(['quartier_id'=>$quartier->id,'source'=>'open-meteo','actif'=>true],['titre'=>"Forte chaleur à {$quartier->nom}",'description'=>"Alerte générée depuis Open-Meteo.",'temperature'=>$w['temperature'],'temperature_max'=>$w['temperature_max'],'temperature_min'=>$w['temperature_min'],'niveau'=>$niveau,'date_debut'=>now(),'date_fin'=>now()->endOfDay()]);return back()->with('success',"Météo actualisée : {$w['temperature']}°C — {$niveau}.");}catch(\RuntimeException $e){return back()->withErrors(['meteo'=>$e->getMessage()]);}} }
